CREATE COLUMN TABLE "TEST_AP"."ODSL" ("AbsEntry" INTEGER CS_INT NOT NULL , "ObjType" NVARCHAR(20) DEFAULT '-1' NOT NULL , "DocEntry" INTEGER CS_INT NOT NULL , "DocLineNum" INTEGER CS_INT NOT NULL , "SchdLine" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50), "WhsCode" NVARCHAR(8), "CfmDate" LONGDATE CS_LONGDATE, "CfmQty" DECIMAL(21,6) CS_FIXED, "FixedCfm" NVARCHAR(1) DEFAULT 'N', "ReqQty" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."ODSL" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$ObjType$DocEntry$DocLineNum$','ObjType','DocEntry','DocLineNum'));
CREATE UNIQUE INDEX "ODSL_SCHD_LINE" ON "TEST_AP"."ODSL" ( "ObjType" ASC, "DocEntry" ASC, "DocLineNum" ASC, "SchdLine" ASC );
CREATE INDEX "ODSL_DOCLINESLD" ON "TEST_AP"."ODSL" ( "ObjType" ASC, "DocEntry" ASC, "DocLineNum" ASC )